"""Tests of pipeline `sas_folder_restructure_wf` — generated by package-factory 0.9.0. Do not edit: change the requirement and run `pkf create`."""
from __future__ import annotations

from pathlib import Path

import pytest

from pkf.cli import main

REPO = Path(__file__).resolve().parents[2]
PIPELINE = 'sas_folder_restructure_wf'
COMPONENTS = [('trigger', 'sas_folder_restructure_schedule'), ('source', 'sas_incoming'), ('destination', 'sas_study_bucket')]


def _ok(*args: str) -> bool:
    """Run one pkf command in the specs repository; True when it reports no error."""
    import os

    old = Path.cwd()
    os.chdir(REPO)
    try:
        return main(["--json", *args]) == 0
    finally:
        os.chdir(old)


@pytest.mark.parametrize(("kind", "component"), COMPONENTS)
def test_component_cases_and_examples(kind: str, component: str) -> None:
    """Every unit test case, function case and example of one component passes."""
    assert _ok("test", kind, component)


def test_pipeline_examples_end_to_end() -> None:
    """The pipeline examples pass through every component."""
    assert _ok("test", "pipeline", PIPELINE)


def test_class_resolves() -> None:
    """The production class builds its resolved pipeline from the dev settings."""
    from pkf_runtime.pipeline import load_class

    pipeline = load_class(REPO / "dags", PIPELINE)("dev")
    assert pipeline.lock()["pipeline"]["name"] == PIPELINE


def test_dag_imports() -> None:
    """The DAG file imports in Airflow and wires one task per component inside the package group."""
    pytest.importorskip("airflow")
    from airflow.models.dagbag import DagBag

    bag = DagBag(dag_folder=str(REPO / "dags" / "pkf_sas_folder_restructure_wf.py"), include_examples=False)
    assert not bag.import_errors
    tasks = {t.task_id for t in bag.dags["pkf_sas_folder_restructure_wf"].tasks}
    assert {"package.source", "package.destination", "report"} <= tasks
